import { postServerData } from '../helper/helper';
import * as Action from '../redux/result_reducer';

/** Thunk — push a new answer to the result array */
export const PushAnswer = (result) => async (dispatch) => {
    try {
        await dispatch(Action.pushResultAction(result));
    } catch (error) {
        console.error('Error pushing answer:', error);
    }
};

/** Thunk — update an existing answer at trace index */
export const updateResult = (payload) => async (dispatch) => {
    try {
        dispatch(Action.updateResultAction(payload));
    } catch (error) {
        console.error('Error updating result:', error);
    }
};

/** Hook — publishes quiz result to the backend (called once on Result page mount) */
export const usePublishResult = (resultData) => {
    const { result, username } = resultData;

    (async () => {
        try {
            if (!result.length || !username) {
                throw new Error("Couldn't publish result: missing result or username.");
            }
            const response = await postServerData(`/api/result`, resultData);
            console.log('Result published:', response);
        } catch (error) {
            console.error('Error publishing result:', error);
        }
    })();
};
